--** SSC-FDM-INF0029 - INFORMATICA LOADS TARGETS SEQUENTIALLY PER TARGETLOADORDER. THE TRANSLATED DBT MODEL USES UNION ALL TO COMBINE ALL PIPELINES INTO A SINGLE ATOMIC QUERY. IF PIPELINE EXECUTION ORDER AFFECTS THE FINAL RESULT, REVIEW THE GENERATED MODEL. **
WITH source_1 AS
(
   SELECT
      BOOKINGS_MEASURE_KEY,
      BKGS_MEASURE_TRANS_TYPE_CODE,
      BOOKINGS_PROCESS_DATE,
      SALES_TERRITORY_KEY,
      SALES_REP_NUMBER,
      DV_CONTRACT_DURATION,
      DV_ANNUALIZED_FLG,
      RU_SERVICE_CONTRACT_START_DTM,
      RU_SERVICE_CONTRACT_END_DTM,
      ANNUITY_TYPE,
      ANNUITY_WEEK,
      ANNUITY_AMT,
      DV_FMV_FLG,
      ADJUSTMENT_CODE
   FROM
      {{ ref('stg_raw__SQ_WI_BKGS_MSR_ATY_SW_PRDT_2') }}
),
source_2 AS
(
   SELECT
      BOOKINGS_MEASURE_KEY,
      BKGS_MEASURE_TRANS_TYPE_CODE,
      BOOKINGS_PROCESS_DATE,
      SALES_TERRITORY_KEY,
      SALES_REP_NUMBER,
      DV_CONTRACT_DURATION,
      DV_ANNUALIZED_FLG,
      RU_SERVICE_CONTRACT_START_DTM,
      RU_SERVICE_CONTRACT_END_DTM,
      ANNUITY_TYPE,
      ANNUITY_WEEK,
      ANNUITY_AMT,
      DV_FMV_FLG,
      ADJUSTMENT_CODE
   FROM
      {{ ref('stg_raw__SQ_WI_BKGS_MSR_ATY_SW_PRDT_21') }}
)
SELECT
   sd.BOOKINGS_MEASURE_KEY AS BOOKINGS_MEASURE_KEY,
   sd.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CODE,
   sd.BOOKINGS_PROCESS_DATE AS BOOKINGS_PROCESS_DATE,
   sd.SALES_TERRITORY_KEY AS SALES_TERRITORY_KEY,
   sd.SALES_REP_NUMBER AS SALES_REP_NUMBER,
   sd.DV_CONTRACT_DURATION AS DV_CONTRACT_DURATION,
   sd.DV_ANNUALIZED_FLG AS DV_ANNUALIZED_FLG,
   sd.RU_SERVICE_CONTRACT_START_DTM AS RU_SERVICE_CONTRACT_START_DTM,
   sd.RU_SERVICE_CONTRACT_END_DTM AS RU_SERVICE_CONTRACT_END_DTM,
   sd.ANNUITY_TYPE AS ANNUITY_TYPE,
   sd.ANNUITY_WEEK AS ANNUITY_WEEK,
   sd.ANNUITY_AMT AS ANNUITY_AMT,
   sd.DV_FMV_FLG AS DV_FMV_FLG,
   sd.ADJUSTMENT_CODE AS ADJUSTMENT_CODE
FROM
   source_1 AS sd
UNION ALL
SELECT
   sd.BOOKINGS_MEASURE_KEY AS BOOKINGS_MEASURE_KEY,
   sd.BKGS_MEASURE_TRANS_TYPE_CODE AS BKGS_MEASURE_TRANS_TYPE_CODE,
   sd.BOOKINGS_PROCESS_DATE AS BOOKINGS_PROCESS_DATE,
   sd.SALES_TERRITORY_KEY AS SALES_TERRITORY_KEY,
   sd.SALES_REP_NUMBER AS SALES_REP_NUMBER,
   sd.DV_CONTRACT_DURATION AS DV_CONTRACT_DURATION,
   sd.DV_ANNUALIZED_FLG AS DV_ANNUALIZED_FLG,
   sd.RU_SERVICE_CONTRACT_START_DTM AS RU_SERVICE_CONTRACT_START_DTM,
   sd.RU_SERVICE_CONTRACT_END_DTM AS RU_SERVICE_CONTRACT_END_DTM,
   sd.ANNUITY_TYPE AS ANNUITY_TYPE,
   sd.ANNUITY_WEEK AS ANNUITY_WEEK,
   sd.ANNUITY_AMT AS ANNUITY_AMT,
   sd.DV_FMV_FLG AS DV_FMV_FLG,
   sd.ADJUSTMENT_CODE AS ADJUSTMENT_CODE
FROM
   source_2 AS sd